"""Fix packaged web asset paths. Run only after the application has stopped."""
import argparse, base64, hashlib, json, subprocess, sys, tempfile
from pathlib import Path
PAYLOAD = {'app/host_service.py': {'old_sha256': '27f83fa991aaaf5b8448c9a95fb7d83a49ef73235c35f2f64ad00b2d64da6c44', 'new_sha256': 'a52ca77d118e5c46c3892ba8b0cc4c60c4cb8cd46f12919c751532863ab3bb59', 'base64': ''}, 'tools/check_project.py': {'old_sha256': '49a01d8560f0e7f957d7cbc96432472c2f999dc709dc7a6101efbb628db6a75d', 'new_sha256': '330a5f53d0405f07d38aa5d4d77e50775671075445123a97fde65d70c6c96c40', 'base64': ''}}
def sha(data): return hashlib.sha256(data).hexdigest()
def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('project_root',type=Path)
    root=parser.parse_args().project_root.resolve()
    manifest_path=root/'release_manifest.json'
    manifest=json.loads(manifest_path.read_text(encoding='utf-8'))
    replacements={}
    for name, item in PAYLOAD.items():
        current=(root/name).read_bytes()
        digest=sha(current)
        if digest not in (item['old_sha256'],item['new_sha256']):
            raise RuntimeError('Unexpected source version; no changes made: '+name)
        if manifest['sha256'].get(name)!=digest:
            raise RuntimeError('Existing manifest differs; no changes made: '+name)
        new=base64.b64decode(item['base64'])
        if sha(new)!=item['new_sha256']: raise RuntimeError('Patch payload hash differs')
        if digest!=item['new_sha256']: replacements[name]=new
    subprocess.run([sys.executable,'-B',str(root/'tools/check_project.py')],check=True)
    if replacements:
        backup=Path(tempfile.mkdtemp(prefix='host_case_backup_',dir=str(root.parent)))
        originals={name:(root/name).read_bytes() for name in replacements}
        originals['release_manifest.json']=manifest_path.read_bytes()
        for name,data in originals.items():
            target=backup/name; target.parent.mkdir(parents=True,exist_ok=True); target.write_bytes(data)
        try:
            for name,data in replacements.items():
                (root/name).write_bytes(data); manifest['sha256'][name]=sha(data)
            manifest_path.write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
            subprocess.run([sys.executable,'-B',str(root/'tools/check_project.py')],check=True)
        except Exception:
            for name,data in originals.items(): (root/name).write_bytes(data)
            raise
        print('Backup:',backup)
    print('HOST_ASSET_CASE_FIX_PASS; hardware_accessed=False')
    print('Restart the Notebook kernel, run its first cell, then start with reuse / False if the board has not been powered off.')
if __name__=='__main__': main()
